METODOS = ("Efectivo", "Yape", "Plin", "Tarjeta", "Transferencia")
COBRANZA = ("ventas.cobranza.ver", "ventas.cobranza.gestionar")


def existentes(apps, schema_editor):
    """RF-VEN-58: métodos de pago de las empresas ya registradas; los roles que registran
    ventas reciben los permisos de cobranza (en una base nueva aún no hay roles)."""
    Empresa = apps.get_model("tenancy", "Empresa")
    MetodoPago = apps.get_model("sales", "MetodoPago")
    for empresa_id in Empresa.objects.values_list("id", flat=True):
        for nombre in METODOS:
            MetodoPago.all_tenants.get_or_create(empresa_id=empresa_id, nombre=nombre)
    Permiso = apps.get_model("tenancy", "Permiso")
    RolPermiso = apps.get_model("tenancy", "RolPermiso")
    roles = list(
        RolPermiso.objects.filter(permiso_id="ventas.venta.registrar").values_list(
            "rol_id", flat=True
        )
    )
    if not roles:
        return
    for codigo in COBRANZA:
        Permiso.objects.get_or_create(codigo=codigo, defaults={"funcionalidad_id": "ventas.ventas"})
        for rol_id in roles:
            RolPermiso.objects.get_or_create(rol_id=rol_id, permiso_id=codigo)


def revertir(apps, schema_editor):
    apps.get_model("tenancy", "RolPermiso").objects.filter(permiso_id__in=COBRANZA).delete()


LINEAS = """
CREATE OR REPLACE FUNCTION fn_pedido_linea_bloqueada() RETURNS trigger AS $$
DECLARE
    v_estado text;
BEGIN
    SELECT estado INTO v_estado FROM sales_pedido WHERE id =
        CASE WHEN TG_OP = 'DELETE' THEN OLD.pedido_id ELSE NEW.pedido_id END;
    IF v_estado = 'CREADO' THEN
        NULL;
    -- 0006b: al facturar (pedido aún Aprobado) solo se escriben el desglose y el costo.
    ELSIF v_estado = 'APROBADO' AND TG_OP = 'UPDATE'
        AND (NEW.pedido_id, NEW.producto_id, NEW.cantidad, NEW.precio, NEW.subtotal)
            IS NOT DISTINCT FROM
            (OLD.pedido_id, OLD.producto_id, OLD.cantidad, OLD.precio, OLD.subtotal) THEN
        NULL;
    ELSE
        RAISE EXCEPTION 'Las líneas de un pedido % no se cambian', lower(v_estado);
    END IF;
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
END $$ LANGUAGE plpgsql;
"""

