# Cuotas inmutables; pagos sin borrar y, una vez registrados, solo se anulan (RF-VEN-56).
COBROS = """
CREATE FUNCTION fn_cuota_inmutable() RETURNS trigger AS $$
BEGIN
    RAISE EXCEPTION 'Las cuotas de una cobranza no se cambian';
END $$ LANGUAGE plpgsql;
CREATE TRIGGER trg_cuota_inmutable BEFORE UPDATE OR DELETE
    ON sales_cuota FOR EACH ROW EXECUTE FUNCTION fn_cuota_inmutable();

CREATE FUNCTION fn_pago_solo_anular() RETURNS trigger AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'Un pago no se borra: se anula';
    END IF;
    IF (NEW.empresa_id, NEW.cobranza_id, NEW.metodo_id, NEW.monto, NEW.fecha, NEW.referencia,
        NEW.registrado_por_id, NEW.registrado_en)
        IS DISTINCT FROM
       (OLD.empresa_id, OLD.cobranza_id, OLD.metodo_id, OLD.monto, OLD.fecha, OLD.referencia,
        OLD.registrado_por_id, OLD.registrado_en)
       OR OLD.anulado_en IS NOT NULL THEN
        RAISE EXCEPTION 'Un pago registrado solo se anula';
    END IF;
    RETURN NEW;
END $$ LANGUAGE plpgsql;
CREATE TRIGGER trg_pago_solo_anular BEFORE UPDATE OR DELETE
    ON sales_pago FOR EACH ROW EXECUTE FUNCTION fn_pago_solo_anular();
"""

